/* ============================================================
   DON'T LOOK BACK — interface + atmosphere
   ============================================================ */

:root {
  --ink: #ded7c7;
  --ink-dim: #8d8779;
  --ink-faint: #575349;
  --red: #b3382d;
  --red-bright: #e04b3a;
  --gold: #d9b76d;
  --cyan: #8fe7e2;
  --bg: #050506;
  --mono: "Courier New", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --display: Georgia, "Times New Roman", "DejaVu Serif", serif;
  --gaze: 0;
  --vignette: 0.62;
  --edge: 0;
  --flash: 1;
  --sat: 1;
  --hue: 0deg;
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  width: 100%;
  background: #000;
  color: var(--ink);
  overflow: hidden;
  overscroll-behavior: none;
  -webkit-tap-highlight-color: transparent;
}

body {
  position: fixed;
  inset: 0;
  font-family: var(--mono);
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: radial-gradient(ellipse at 50% 40%, #0b0c0d 0%, #050506 55%, #010101 100%);
}

#viewport {
  position: absolute;
  inset: 0;
  overflow: hidden;
  background: #020203;
}

#scene {
  position: absolute;
  inset: -2%;
  width: 104%;
  height: 104%;
  display: block;
  image-rendering: auto;
  filter: saturate(var(--sat)) hue-rotate(var(--hue)) contrast(1.04) brightness(1.02);
  will-change: transform, filter;
  transform-origin: 50% 50%;
}

/* ---------------- atmosphere layers ---------------- */

.fx {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 3;
}

.tint {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 50%, rgba(120, 10, 6, 0) 42%, rgba(120, 10, 6, calc(var(--gaze) * 0.22)) 100%);
  mix-blend-mode: screen;
  opacity: .9;
}

.vignette {
  position: absolute;
  inset: -2px;
  background:
    radial-gradient(ellipse at 50% 50%, rgba(0,0,0,0) 30%, rgba(0,0,0, calc(var(--vignette) * .55)) 62%, rgba(0,0,0, calc(var(--vignette) * .96)) 100%),
    linear-gradient(to bottom, rgba(0,0,0,.55) 0%, rgba(0,0,0,0) 18%, rgba(0,0,0,0) 78%, rgba(0,0,0,.75) 100%);
}

.edge-glow {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 55%, rgba(150,20,10,0) 55%, rgba(150,20,10, calc(var(--edge) * .35)) 100%);
  mix-blend-mode: screen;
  opacity: 0;
  transition: opacity .4s linear;
}
body.reality-broken-1 .edge-glow { opacity: .45; }
body.reality-broken-2 .edge-glow { opacity: .9; }

.grain {
  position: absolute;
  inset: -50%;
  width: 200%;
  height: 200%;
  background-image: var(--grain, none);
  background-repeat: repeat;
  background-size: 160px 160px;
  opacity: .085;
  mix-blend-mode: overlay;
  animation: grainShift .24s steps(2) infinite;
}

@keyframes grainShift {
  0% { transform: translate3d(0, 0, 0); }
  25% { transform: translate3d(-2.4%, 1.6%, 0); }
  50% { transform: translate3d(1.8%, -2.2%, 0); }
  75% { transform: translate3d(-1.2%, -1.4%, 0); }
  100% { transform: translate3d(2.1%, 2%, 0); }
}

.scanlines {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    to bottom,
    rgba(0,0,0,.16) 0px,
    rgba(0,0,0,.16) 1px,
    rgba(255,255,255,0) 1px,
    rgba(255,255,255,0) 3px
  );
  opacity: .28;
  mix-blend-mode: multiply;
}

.flash {
  position: absolute;
  inset: 0;
  background: #dfe9e4;
  opacity: 0;
  mix-blend-mode: screen;
  transition: opacity .12s linear;
}
.flash.on { opacity: .82; transition: none; }

.tearbar {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 0;
  background: rgba(223, 233, 228, .16);
  mix-blend-mode: screen;
  opacity: 0;
}
body.fracturing .tearbar {
  opacity: 1;
  animation: tearMove .52s steps(1) 2;
}
@keyframes tearMove {
  0% { top: 22%; height: 5%; transform: translateX(-3%); }
  25% { top: 61%; height: 2%; transform: translateX(4%); }
  50% { top: 37%; height: 8%; transform: translateX(-6%); }
  75% { top: 76%; height: 1.5%; transform: translateX(2%); }
  100% { top: 12%; height: 4%; transform: translateX(0); }
}

body.fracturing #scene { animation: canvasGlitch .6s steps(1) 1; }
@keyframes canvasGlitch {
  0% { transform: translate(0,0) scale(1.04); filter: invert(0); }
  12% { transform: translate(-8px, 3px) scale(1.05); filter: invert(1) hue-rotate(90deg); }
  20% { transform: translate(6px, -4px) scale(1.06); filter: invert(0); }
  31% { transform: translate(-3px, 6px) scale(1.045); filter: contrast(1.8) saturate(2); }
  44% { transform: translate(9px, 1px) scale(1.05); filter: invert(0); }
  57% { transform: translate(-5px, -6px) scale(1.055); filter: hue-rotate(180deg) saturate(0); }
  70% { transform: translate(2px, 4px) scale(1.04); filter: invert(0); }
  100% { transform: translate(0,0) scale(1.04); filter: invert(0); }
}

body.shake #scene { animation: shakeCanvas .35s linear; }
@keyframes shakeCanvas {
  0%, 100% { transform: translate(0,0) scale(1.035); }
  20% { transform: translate(-5px, 3px) scale(1.04); }
  40% { transform: translate(4px, -4px) scale(1.04); }
  60% { transform: translate(-3px, 2px) scale(1.035); }
  80% { transform: translate(3px, 1px) scale(1.04); }
}

@media (prefers-reduced-motion: reduce) {
  .grain { animation: none; }
  body.no-flash .grain { animation: none; }
}

/* ---------------- HUD ---------------- */

.hud {
  position: absolute;
  inset: 0;
  z-index: 6;
  pointer-events: none;
  transition: opacity .5s ease;
  padding: calc(var(--safe-t) + 16px) calc(var(--safe-r) + 20px) calc(var(--safe-b) + 12px) calc(var(--safe-l) + 20px);
}
.hud.is-hidden { opacity: 0; visibility: hidden; }

.hud-top {
  display: flex;
  align-items: flex-start;
  gap: 22px;
  justify-content: space-between;
  text-shadow: 0 1px 8px rgba(0,0,0,.9);
}

.hud-brand {
  font-size: 10px;
  letter-spacing: .26em;
  color: var(--ink);
  line-height: 1.55;
  opacity: .82;
  white-space: nowrap;
}
.hud-brand span {
  display: block;
  color: var(--ink-dim);
  letter-spacing: .34em;
  font-size: 9px;
}

.hud-meter {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 9px;
  letter-spacing: .3em;
  color: var(--ink-dim);
}
.hud-meter .pips {
  color: var(--gold);
  font-size: 15px;
  letter-spacing: .28em;
  text-shadow: 0 0 12px rgba(217, 183, 109, .5);
}
.reality-meter .pips { color: var(--ink); text-shadow: 0 0 10px rgba(220,220,200,.3); }
.reality-meter.danger .pips { color: var(--red-bright); text-shadow: 0 0 14px rgba(224, 75, 58, .7); }

.gaze {
  position: absolute;
  top: calc(var(--safe-t) + 72px);
  left: 50%;
  width: min(340px, 56vw);
  transform: translateX(-50%);
  text-align: center;
  opacity: 0;
  transition: opacity .25s ease;
}
.gaze.on { opacity: 1; }
.gaze-label {
  font-size: 9px;
  letter-spacing: .42em;
  color: var(--ink-dim);
  margin-bottom: 8px;
  text-shadow: 0 1px 10px #000;
  transition: color .2s;
}
.gaze.hot .gaze-label { color: var(--red-bright); animation: textJitter .12s steps(2) infinite; }
.gaze-bar {
  height: 2px;
  background: rgba(220, 215, 200, .16);
  overflow: hidden;
}
.gaze-fill {
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, var(--ink-dim), var(--ink) 55%, var(--red-bright));
  box-shadow: 0 0 14px rgba(224, 75, 58, .6);
  transition: width .08s linear;
}
@keyframes textJitter {
  0% { transform: translate(0,0); }
  50% { transform: translate(1px,-1px); }
  100% { transform: translate(-1px,1px); }
}

.reticle {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 22px;
  height: 22px;
  transform: translate(-50%, -50%);
  opacity: .6;
}
.reticle::before, .reticle::after {
  content: "";
  position: absolute;
  background: rgba(225, 220, 205, .8);
}
.reticle::before { left: 50%; top: 8px; width: 1px; height: 6px; transform: translateX(-50%); }
.reticle::after { top: 50%; left: 8px; height: 1px; width: 6px; transform: translateY(-50%); }
.reticle span {
  position: absolute;
  inset: 7px;
  border: 1px solid rgba(225, 220, 205, .55);
  border-radius: 50%;
  transition: transform .12s, border-color .12s, box-shadow .12s;
}
.reticle.locked span {
  transform: scale(2.3);
  border-color: rgba(224, 75, 58, .9);
  box-shadow: 0 0 16px rgba(224, 75, 58, .55);
}

.message {
  position: absolute;
  left: 50%;
  bottom: 20vh;
  transform: translateX(-50%);
  width: min(740px, 84vw);
  text-align: center;
  font-size: clamp(10px, 1.05vw, 13px);
  letter-spacing: .22em;
  line-height: 1.9;
  color: var(--ink);
  text-transform: uppercase;
  text-shadow: 0 0 18px #000, 0 0 4px #000;
  opacity: 0;
  transition: opacity .35s ease;
}
.message.on { opacity: .92; }
.message.glitch { animation: textJitter .09s steps(2) infinite; color: var(--red-bright); }
.message em { font-style: normal; color: var(--red-bright); }

.hint {
  position: absolute;
  left: 50%;
  bottom: calc(var(--safe-b) + 20px);
  transform: translateX(-50%);
  font-size: 8.5px;
  letter-spacing: .3em;
  color: var(--ink-faint);
  white-space: nowrap;
  transition: opacity .6s ease;
}
.hint.fade { opacity: 0; }

.compass {
  position: absolute;
  left: 50%;
  bottom: calc(var(--safe-b) + 58px);
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 8px;
  letter-spacing: .34em;
  color: var(--gold);
  opacity: 0;
  transition: opacity .3s ease;
}
.compass.on { opacity: .85; }
.compass-arrow {
  width: 0;
  height: 0;
  border-left: 7px solid transparent;
  border-right: 7px solid transparent;
  border-bottom: 16px solid var(--gold);
  filter: drop-shadow(0 0 8px rgba(217,183,109,.7));
  transform-origin: 50% 58%;
}
.compass-arrow.onscreen { border-bottom-color: var(--ink); }

.pause-btn {
  position: absolute;
  right: calc(var(--safe-r) + 18px);
  top: calc(var(--safe-t) + 14px);
  width: 34px;
  height: 34px;
  padding: 0;
  border: 1px solid rgba(222, 215, 199, .22);
  background: rgba(7, 8, 8, .4);
  color: var(--ink-dim);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: .1em;
  cursor: pointer;
  pointer-events: auto;
  transition: .2s;
}
.pause-btn:hover { color: var(--ink); border-color: rgba(222, 215, 199, .5); }

/* ---------------- touch controls ---------------- */

.touch-ui {
  position: absolute;
  inset: 0;
  z-index: 7;
  pointer-events: none;
  display: none;
}

.stick-base {
  position: absolute;
  width: 124px;
  height: 124px;
  border-radius: 50%;
  border: 1px solid rgba(222, 215, 199, .17);
  background: radial-gradient(circle, rgba(222,215,199,.05), rgba(0,0,0,.1));
  left: calc(var(--safe-l) + 30px);
  bottom: calc(var(--safe-b) + 34px);
  opacity: 0;
  transition: opacity .18s;
  pointer-events: none;
}
.stick-base.on { opacity: 1; }
.stick-knob {
  position: absolute;
  width: 54px;
  height: 54px;
  left: 50%;
  top: 50%;
  margin: -27px 0 0 -27px;
  border-radius: 50%;
  border: 1px solid rgba(222, 215, 199, .35);
  background: rgba(222, 215, 199, .08);
  box-shadow: 0 0 24px rgba(0,0,0,.6);
}

.touch-btn {
  position: absolute;
  right: calc(var(--safe-r) + 26px);
  bottom: calc(var(--safe-b) + 42px);
  width: 84px;
  height: 84px;
  border-radius: 50%;
  border: 1px solid rgba(222, 215, 199, .3);
  background: rgba(8, 9, 9, .45);
  color: var(--ink);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: .22em;
  pointer-events: auto;
  backdrop-filter: blur(3px);
  transition: .15s;
  touch-action: none;
}
.touch-btn:active { background: rgba(222, 215, 199, .16); transform: scale(.96); }
.listen-btn { bottom: calc(var(--safe-b) + 140px); width: 66px; height: 66px; font-size: 7.5px; }
.listen-btn.cooldown { opacity: .32; }

@media (pointer: coarse) {
  .touch-ui { display: block; }
  .hint { display: none; }
  .pause-btn { top: calc(var(--safe-t) + 56px); }
}
@media (max-width: 820px) {
  .hint { font-size: 7px; letter-spacing: .18em; max-width: 90vw; white-space: normal; text-align: center; }
  .hud-brand { display: none; }
  .hud-top { justify-content: space-between; }
  .message { bottom: 24vh; font-size: 10px; letter-spacing: .16em; }
}

/* ---------------- overlays ---------------- */

.overlay {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: flex;
  opacity: 1;
  visibility: visible;
  transition: opacity .45s ease, visibility .45s;
  overflow: hidden;
}
.overlay.is-hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.menu {
  background:
    linear-gradient(90deg, rgba(3,3,4,.94) 0%, rgba(3,3,4,.8) 38%, rgba(3,3,4,.18) 68%, rgba(3,3,4,.55) 100%),
    radial-gradient(ellipse at 72% 46%, rgba(0,0,0,0) 0%, rgba(0,0,0,.55) 75%);
}
.menu::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, rgba(0,0,0,.55), transparent 26%, transparent 72%, rgba(0,0,0,.8));
  pointer-events: none;
}
.menu-bg { position: absolute; inset: 0; pointer-events: none; }

.menu-inner {
  position: relative;
  z-index: 2;
  align-self: center;
  margin-left: clamp(24px, 7vw, 120px);
  width: min(650px, 86vw);
  padding: clamp(24px, 4vh, 48px) 0;
}

.kicker {
  display: flex;
  align-items: center;
  gap: 14px;
  font-size: 9px;
  letter-spacing: .48em;
  color: var(--ink-dim);
  margin-bottom: clamp(18px, 3.4vh, 34px);
  opacity: .8;
}
.kicker .line {
  display: inline-block;
  width: 42px;
  height: 1px;
  background: var(--red);
}

.title {
  margin: 0;
  font-family: var(--display);
  font-weight: 700;
  font-size: clamp(56px, 9.6vw, 148px);
  line-height: .78;
  letter-spacing: -.035em;
  text-transform: uppercase;
  color: var(--ink);
  filter: drop-shadow(0 4px 30px rgba(0,0,0,.8));
}
.title .word { display: block; }
.title .ghost {
  color: rgba(222, 215, 199, .03);
  -webkit-text-stroke: 1px rgba(222, 215, 199, .55);
  letter-spacing: -.02em;
}
.title .solid { color: var(--ink); }
.title .red {
  color: var(--red);
  text-shadow: 2px 0 rgba(140, 230, 225, .12), -2px 0 rgba(224, 75, 58, .25);
  animation: redFlicker 7s steps(1) infinite;
}
@keyframes redFlicker {
  0%, 92%, 100% { opacity: 1; }
  93% { opacity: .45; }
  94% { opacity: 1; }
  96% { opacity: .28; }
  97% { opacity: 1; }
}

.tagline {
  margin: clamp(22px, 3.4vh, 36px) 0 0;
  max-width: 420px;
  font-size: clamp(10px, 1.05vw, 12.5px);
  line-height: 2;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--ink-dim);
}
.tagline br { display: block; }

.primary {
  position: relative;
  margin-top: clamp(24px, 4vh, 42px);
  display: inline-flex;
  align-items: center;
  gap: 18px;
  padding: 18px 34px;
  border: 1px solid rgba(222, 215, 199, .5);
  background: rgba(8, 9, 9, .25);
  color: var(--ink);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: .34em;
  text-transform: uppercase;
  cursor: pointer;
  overflow: hidden;
  transition: color .25s, border-color .25s, background .25s;
}
.primary i {
  display: block;
  width: 18px;
  height: 1px;
  background: currentColor;
  transition: width .25s;
}
.primary:hover { background: var(--ink); color: #080808; border-color: var(--ink); }
.primary:hover i { width: 34px; }
.primary:focus-visible { outline: 1px solid var(--red); outline-offset: 4px; }

.menu-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 14px 26px;
  align-items: center;
  margin-top: clamp(22px, 3.4vh, 34px);
  padding-top: 18px;
  border-top: 1px solid rgba(222, 215, 199, .12);
  max-width: 560px;
}
.controls-mini {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 18px;
  font-size: 8px;
  letter-spacing: .2em;
  color: var(--ink-faint);
}
.controls-mini b { color: var(--ink-dim); font-weight: 400; }
.notice {
  font-size: 7.5px;
  letter-spacing: .18em;
  color: var(--ink-faint);
  opacity: .7;
}

.settings {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px 26px;
  margin-top: 20px;
  max-width: 560px;
  font-size: 8px;
  letter-spacing: .2em;
  color: var(--ink-faint);
}
.setting { display: flex; align-items: center; gap: 10px; }
.setting > span { white-space: nowrap; }
.setting input[type=range] {
  -webkit-appearance: none;
  appearance: none;
  width: 110px;
  height: 14px;
  background: transparent;
  cursor: pointer;
}
.setting input[type=range]::-webkit-slider-runnable-track {
  height: 1px;
  background: rgba(222, 215, 199, .3);
}
.setting input[type=range]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 8px;
  height: 8px;
  margin-top: -3.5px;
  border-radius: 50%;
  background: var(--ink);
}
.setting input[type=range]::-moz-range-track { height: 1px; background: rgba(222,215,199,.3); }
.setting input[type=range]::-moz-range-thumb { width: 8px; height: 8px; border: 0; border-radius: 50%; background: var(--ink); }
.setting.check { cursor: pointer; }
.setting input[type=checkbox] {
  appearance: none;
  width: 11px;
  height: 11px;
  border: 1px solid rgba(222, 215, 199, .35);
  background: transparent;
  cursor: pointer;
  position: relative;
}
.setting input[type=checkbox]:checked { background: var(--ink-dim); border-color: var(--ink-dim); }
.setting input[type=checkbox]:checked::after {
  content: "";
  position: absolute;
  inset: 2px;
  background: #080808;
}

.menu-foot {
  position: absolute;
  z-index: 2;
  left: clamp(24px, 7vw, 120px);
  bottom: calc(var(--safe-b) + 20px);
  font-size: 7.5px;
  letter-spacing: .34em;
  color: var(--ink-faint);
  opacity: .65;
}

/* pause / death / win cards */

.pause, .death, .win {
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: rgba(2, 2, 3, .74);
  backdrop-filter: blur(6px);
}
.death { background: rgba(8, 2, 2, .8); }
.win { background: radial-gradient(ellipse at 50% 45%, rgba(210, 220, 210, .1), rgba(3, 4, 4, .95) 60%); backdrop-filter: blur(8px); }

.card {
  position: relative;
  width: min(460px, 92vw);
  text-align: center;
  padding: clamp(28px, 5vh, 48px) clamp(22px, 5vw, 46px);
  border: 1px solid rgba(222, 215, 199, .16);
  background: linear-gradient(180deg, rgba(12, 13, 13, .92), rgba(5, 6, 6, .96));
  box-shadow: 0 30px 120px rgba(0,0,0,.9);
  animation: cardIn .5s cubic-bezier(.2,.8,.2,1);
}
@keyframes cardIn {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: none; }
}
.card::before {
  content: "";
  position: absolute;
  inset: 6px;
  border: 1px solid rgba(222, 215, 199, .06);
  pointer-events: none;
}
.card-kicker {
  font-size: 8px;
  letter-spacing: .5em;
  color: var(--red);
  margin-bottom: 16px;
}
.card h2 {
  margin: 0;
  font-family: var(--display);
  font-size: clamp(34px, 5.4vw, 58px);
  line-height: .92;
  letter-spacing: .01em;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--ink);
}
.card-sub {
  margin: 18px auto 0;
  max-width: 330px;
  font-size: 9px;
  line-height: 2.1;
  letter-spacing: .2em;
  text-transform: uppercase;
  color: var(--ink-dim);
}
.stats {
  display: flex;
  justify-content: center;
  gap: 28px;
  margin: 24px 0 4px;
  font-size: 8px;
  letter-spacing: .2em;
  color: var(--ink-faint);
}
.stats b {
  display: block;
  font-size: 19px;
  font-weight: 400;
  letter-spacing: .05em;
  color: var(--ink);
  margin-top: 7px;
}
.card .primary { margin-top: 26px; }
.ghost-btn {
  display: block;
  margin: 20px auto 0;
  padding: 6px;
  border: 0;
  background: none;
  color: var(--ink-faint);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: .26em;
  cursor: pointer;
  text-transform: uppercase;
}
.ghost-btn:hover { color: var(--ink); }

.win-card .card-kicker { color: var(--cyan); }
.win-card h2 { color: #e9e6da; }

/* jumpscare */

.jumpscare {
  position: absolute;
  inset: 0;
  z-index: 40;
  background: #000;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  overflow: hidden;
}
.jumpscare.active {
  opacity: 1;
  visibility: visible;
  animation: scareShake .09s steps(2) infinite;
}
.jumpscare img {
  position: absolute;
  left: 50%;
  top: 50%;
  height: 118%;
  width: auto;
  max-width: none;
  transform: translate(-50%, -48%) scale(.55);
  filter: contrast(1.5) brightness(.92) saturate(.6);
  animation: scareLunge .55s cubic-bezier(.15,.9,.25,1) forwards;
}
@keyframes scareLunge {
  0% { transform: translate(-50%, -48%) scale(.5); opacity: .2; }
  45% { transform: translate(-50%, -50%) scale(1.28); opacity: 1; }
  100% { transform: translate(-50%, -52%) scale(1.42); opacity: 1; }
}
.jumpscare-static {
  position: absolute;
  inset: 0;
  background-image: var(--grain, none);
  background-size: 220px 220px;
  opacity: .35;
  mix-blend-mode: screen;
  animation: grainShift .1s steps(2) infinite;
}
@keyframes scareShake {
  0% { transform: translate(0,0); }
  50% { transform: translate(-2px, 1px); }
  100% { transform: translate(2px, -1px); }
}

/* rotate hint for tiny portrait phones */

.rotate-hint {
  display: none;
  position: absolute;
  z-index: 30;
  left: 50%;
  bottom: calc(var(--safe-b) + 8px);
  transform: translateX(-50%);
  font-size: 7px;
  letter-spacing: .3em;
  color: var(--ink-faint);
  opacity: .65;
  pointer-events: none;
  white-space: nowrap;
}
@media (max-width: 520px) and (orientation: portrait) {
  .rotate-hint { display: block; }
  .menu-foot { display: none; }
  .menu-inner { align-self: flex-start; margin-top: 8vh; }
  .title { font-size: clamp(52px, 17vw, 82px); }
}

/* caption style for short viewports */

@media (max-height: 620px) and (orientation: landscape) {
  .menu-inner { padding: 10px 0; }
  .kicker { margin-bottom: 14px; }
  .title { font-size: clamp(44px, 11vh, 100px); }
  .tagline { margin-top: 14px; line-height: 1.7; }
  .primary { margin-top: 18px; padding: 13px 26px; }
  .menu-meta { margin-top: 16px; padding-top: 12px; }
  .settings { margin-top: 12px; }
  .menu-foot { display: none; }
}

.noscript {
  position: fixed;
  inset: 0;
  display: grid;
  place-items: center;
  background: #000;
  color: var(--ink);
  z-index: 99;
  font-size: 12px;
  letter-spacing: .3em;
}

/* ============================================================
   Level generation, pathfinding, line of sight
   ============================================================ */

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function shuffle(list, rand) {
  for (let i = list.length - 1; i > 0; i--) {
    const j = (rand() * (i + 1)) | 0;
    const t = list[i]; list[i] = list[j]; list[j] = t;
  }
  return list;
}

function hash2(x, y) {
  const s = Math.sin(x * 127.1 + y * 311.7) * 43758.5453123;
  return s - Math.floor(s);
}

const DIRS = [[2, 0], [-2, 0], [0, 2], [0, -2]];

function isRoom(x, y) {
  return (x & 1) === 1 && (y & 1) === 1;
}

export function bfsDistances(level, sx, sy) {
  const { w, h, grid } = level;
  const dist = new Int16Array(w * h).fill(-1);
  if (sx < 0 || sy < 0 || sx >= w || sy >= h || grid[sy * w + sx] !== 0) return dist;
  const queue = new Int32Array(w * h);
  let head = 0, tail = 0;
  dist[sy * w + sx] = 0;
  queue[tail++] = sy * w + sx;
  while (head < tail) {
    const cur = queue[head++];
    const x = cur % w, y = (cur / w) | 0;
    const d = dist[cur];
    if (x + 1 < w && grid[cur + 1] === 0 && dist[cur + 1] < 0) { dist[cur + 1] = d + 1; queue[tail++] = cur + 1; }
    if (x - 1 >= 0 && grid[cur - 1] === 0 && dist[cur - 1] < 0) { dist[cur - 1] = d + 1; queue[tail++] = cur - 1; }
    if (y + 1 < h && grid[cur + w] === 0 && dist[cur + w] < 0) { dist[cur + w] = d + 1; queue[tail++] = cur + w; }
    if (y - 1 >= 0 && grid[cur - w] === 0 && dist[cur - w] < 0) { dist[cur - w] = d + 1; queue[tail++] = cur - w; }
  }
  return dist;
}

export function findPath(level, from, to) {
  const { w, h, grid } = level;
  const startIdx = (from.y | 0) * w + (from.x | 0);
  const goalIdx = (to.y | 0) * w + (to.x | 0);
  if (startIdx === goalIdx) return [];
  if (grid[goalIdx] !== 0 || grid[startIdx] !== 0) return [];
  const prev = new Int32Array(w * h).fill(-1);
  const seen = new Uint8Array(w * h);
  const queue = new Int32Array(w * h);
  let head = 0, tail = 0;
  queue[tail++] = startIdx;
  seen[startIdx] = 1;
  let found = false;
  while (head < tail) {
    const cur = queue[head++];
    if (cur === goalIdx) { found = true; break; }
    const x = cur % w, y = (cur / w) | 0;
    const neigh = [
      cur + 1, cur - 1, cur + w, cur - w,
    ];
    for (let i = 0; i < 4; i++) {
      const n = neigh[i];
      if (n < 0 || n >= w * h) continue;
      const nx = n % w, ny = (n / w) | 0;
      if (Math.abs(nx - x) + Math.abs(ny - y) !== 1) continue;
      if (grid[n] !== 0 || seen[n]) continue;
      seen[n] = 1;
      prev[n] = cur;
      queue[tail++] = n;
    }
  }
  if (!found) return [];
  const path = [];
  let cur = goalIdx;
  while (cur !== startIdx && cur >= 0) {
    path.push({ x: cur % w, y: (cur / w) | 0 });
    cur = prev[cur];
  }
  path.reverse();
  return path;
}

export function hasLineOfSight(level, x0, y0, x1, y1) {
  const { w, h, grid } = level;
  const dx = x1 - x0, dy = y1 - y0;
  const dist = Math.hypot(dx, dy);
  if (dist < 0.001) return true;
  const steps = Math.max(2, Math.ceil(dist / 0.07));
  for (let i = 1; i < steps; i++) {
    const t = i / steps;
    const x = x0 + dx * t, y = y0 + dy * t;
    const cx = x | 0, cy = y | 0;
    if (cx < 0 || cy < 0 || cx >= w || cy >= h) return false;
    if (grid[cy * w + cx] !== 0) return false;
  }
  return true;
}

export function generateLevel(seed = (Math.random() * 0xffffffff) >>> 0) {
  const rand = mulberry32(seed);
  const w = 19, h = 19;
  const grid = new Uint8Array(w * h).fill(1);
  const at = (x, y) => y * w + x;

  // Carve a perfect maze on odd coordinates.
  grid[at(1, 1)] = 0;
  const stack = [[1, 1]];
  const visited = new Set(['1,1']);
  while (stack.length) {
    const [cx, cy] = stack[stack.length - 1];
    const dirs = shuffle(DIRS.slice(), rand);
    let moved = false;
    for (const [dx, dy] of dirs) {
      const nx = cx + dx, ny = cy + dy;
      if (nx > 0 && nx < w - 1 && ny > 0 && ny < h - 1 && !visited.has(nx + ',' + ny)) {
        grid[at(cx + dx / 2, cy + dy / 2)] = 0;
        grid[at(nx, ny)] = 0;
        visited.add(nx + ',' + ny);
        stack.push([nx, ny]);
        moved = true;
        break;
      }
    }
    if (!moved) stack.pop();
  }

  const level = { seed, w, h, grid, wallType: null };

  const rooms = [];
  for (let y = 1; y < h - 1; y += 2) {
    for (let x = 1; x < w - 1; x += 2) rooms.push({ x, y });
  }

  const openNeighbors = (x, y) => {
    let n = 0;
    if (grid[at(x + 1, y)] === 0) n++;
    if (grid[at(x - 1, y)] === 0) n++;
    if (grid[at(x, y + 1)] === 0) n++;
    if (grid[at(x, y - 1)] === 0) n++;
    return n;
  };

  // Braid some dead ends so the maze has loops and fewer frustrating pockets.
  const deadEnds = rooms.filter(r => openNeighbors(r.x, r.y) === 1);
  shuffle(deadEnds, rand);
  for (const room of deadEnds) {
    if (rand() > 0.6) continue;
    const choices = shuffle([[0, -1], [1, 0], [0, 1], [-1, 0]], rand);
    for (const [dx, dy] of choices) {
      const wx = room.x + dx, wy = room.y + dy;
      const ox = room.x + dx * 2, oy = room.y + dy * 2;
      if (ox <= 0 || oy <= 0 || ox >= w - 1 || oy >= h - 1) continue;
      if (grid[at(wx, wy)] === 1 && grid[at(ox, oy)] === 0) {
        grid[at(wx, wy)] = 0;
        break;
      }
    }
  }

  // A couple of extra breaches for flow.
  for (let i = 0; i < 14; i++) {
    const x = 2 + ((rand() * ((w - 5) / 2)) | 0) * 2;
    const y = 2 + ((rand() * ((h - 5) / 2)) | 0) * 2;
    const horizontal = rand() < 0.5;
    const wx = horizontal ? x + 1 : x;
    const wy = horizontal ? y : y + 1;
    const ax = horizontal ? x : x;
    const ay = horizontal ? y : y;
    const bx = horizontal ? x + 2 : x;
    const by = horizontal ? y : y + 2;
    if (ax > 0 && ay > 0 && bx < w && by < h &&
        grid[at(ax, ay)] === 0 && grid[at(bx, by)] === 0 && grid[at(wx, wy)] === 1) {
      grid[at(wx, wy)] = 0;
    }
  }

  // Wall material zones.
  const wallType = new Uint8Array(w * h);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      if (grid[at(x, y)] === 0) continue;
      if (x === 0 || y === 0 || x === w - 1 || y === h - 1) {
        wallType[at(x, y)] = 1;
        continue;
      }
      const zone = hash2((x / 3) | 0, (y / 3) | 0);
      const rare = hash2(x * 7.31, y * 3.77);
      if (rare > 0.965) wallType[at(x, y)] = 4;
      else if (zone < 0.54) wallType[at(x, y)] = 1;
      else if (zone < 0.78) wallType[at(x, y)] = 2;
      else wallType[at(x, y)] = 3;
    }
  }
  level.wallType = wallType;

  // Pick a dead-end start room, or a corner.
  const starts = rooms.filter(r => openNeighbors(r.x, r.y) === 1);
  const startRoom = starts.length ? starts[(rand() * starts.length) | 0] : { x: 1, y: 1 };
  level.start = { x: startRoom.x, y: startRoom.y };

  const distFromStart = bfsDistances(level, startRoom.x, startRoom.y);

  // Exit = the farthest reachable room.
  let exitRoom = startRoom, best = -1;
  for (const room of rooms) {
    const d = distFromStart[at(room.x, room.y)];
    if (d > best) { best = d; exitRoom = room; }
  }
  level.exit = { x: exitRoom.x, y: exitRoom.y };

  // Sigils: distant rooms, spread apart.
  const candidates = rooms
    .filter(r => !(r.x === startRoom.x && r.y === startRoom.y))
    .filter(r => !(r.x === exitRoom.x && r.y === exitRoom.y))
    .filter(r => distFromStart[at(r.x, r.y)] > 4)
    .sort((a, b) => distFromStart[at(b.x, b.y)] - distFromStart[at(a.x, a.y)]);

  const sigils = [];
  const sigilDistances = [];
  for (const room of candidates) {
    if (sigils.length >= 3) break;
    const d = bfsDistances(level, room.x, room.y);
    let ok = true;
    for (const s of sigils) {
      const sd = d[at(s.x, s.y)];
      if (sd < 0 || sd < 7) { ok = false; break; }
    }
    if (!ok) continue;
    sigils.push({ x: room.x, y: room.y });
    sigilDistances.push(distFromStart[at(room.x, room.y)]);
  }
  // Fallbacks if spacing was too strict.
  for (const room of candidates) {
    if (sigils.length >= 3) break;
    if (sigils.some(s => s.x === room.x && s.y === room.y)) continue;
    sigils.push({ x: room.x, y: room.y });
  }
  level.sigils = sigils;

  // Monster starts far away, preferably on the far side of the exit.
  const monsterCandidates = rooms
    .filter(r => !(r.x === startRoom.x && r.y === startRoom.y))
    .filter(r => !(r.x === exitRoom.x && r.y === exitRoom.y))
    .filter(r => !sigils.some(s => s.x === r.x && s.y === r.y))
    .filter(r => distFromStart[at(r.x, r.y)] > 8)
    .sort((a, b) => distFromStart[at(a.x, b.x)] - distFromStart[at(b.x, b.y)]);
  level.monsterSpawn = monsterCandidates.length
    ? monsterCandidates[(rand() * Math.min(monsterCandidates.length, 8)) | 0]
    : { x: exitRoom.x, y: exitRoom.y };

  level.distFromStart = distFromStart;

  // Player facing: toward an open neighbour.
  const facingOptions = [];
  if (grid[at(startRoom.x + 1, startRoom.y)] === 0) facingOptions.push(0);
  if (grid[at(startRoom.x, startRoom.y + 1)] === 0) facingOptions.push(Math.PI / 2);
  if (grid[at(startRoom.x - 1, startRoom.y)] === 0) facingOptions.push(Math.PI);
  if (grid[at(startRoom.x, startRoom.y - 1)] === 0) facingOptions.push(-Math.PI / 2);
  // Face away from the monster spawn when possible.
  const toMonster = Math.atan2(level.monsterSpawn.y - startRoom.y, level.monsterSpawn.x - startRoom.x);
  facingOptions.sort((a, b) => {
    const da = Math.abs(Math.atan2(Math.sin(a - toMonster), Math.cos(a - toMonster)));
    const db = Math.abs(Math.atan2(Math.sin(b - toMonster), Math.cos(b - toMonster)));
    return db - da;
  });
  level.startAngle = facingOptions.length ? facingOptions[0] : 0;

  // Decorative eyes in side rooms.
  const eyeRooms = shuffle(rooms.filter(r =>
    !sigils.some(s => s.x === r.x && s.y === r.y) &&
    !(r.x === startRoom.x && r.y === startRoom.y) &&
    !(r.x === exitRoom.x && r.y === exitRoom.y)
  ), rand).slice(0, 7);
  level.watchers = eyeRooms.map(r => ({
    x: r.x + 0.5 + (rand() - 0.5) * 0.35,
    y: r.y + 0.5 + (rand() - 0.5) * 0.35,
    height: 1.45 + rand() * 0.25,
    phase: rand() * Math.PI * 2,
  }));

  level.isWall = (x, y) => {
    const cx = Math.floor(x), cy = Math.floor(y);
    if (cx < 0 || cy < 0 || cx >= w || cy >= h) return true;
    return grid[cy * w + cx] !== 0;
  };

  return level;
}

export function cellOf(x, y) {
  return { x: Math.floor(x), y: Math.floor(y) };
}

export function cellCenter(c) {
  return { x: c.x + 0.5, y: c.y + 0.5 };
}

/* ============================================================
   Procedural textures + sprites. Everything is generated at
   runtime so the game has zero external assets.
   ============================================================ */

import { mulberry32 } from './maze.js';

const TEX = 128;

function makeCanvas(w, h) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  return c;
}

function packCanvas(canvas) {
  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  const img = ctx.getImageData(0, 0, canvas.width, canvas.height);
  return {
    w: canvas.width,
    h: canvas.height,
    data: new Uint32Array(img.data.buffer.slice(0)),
    rgba: img.data,
  };
}

function grainPixels(ctx, w, h, rand, amount) {
  const img = ctx.getImageData(0, 0, w, h);
  const d = img.data;
  for (let i = 0; i < d.length; i += 4) {
    if (d[i + 3] === 0) continue;
    const n = (rand() - 0.5) * amount;
    d[i] = Math.max(0, Math.min(255, d[i] + n));
    d[i + 1] = Math.max(0, Math.min(255, d[i + 1] + n));
    d[i + 2] = Math.max(0, Math.min(255, d[i + 2] + n * 0.9));
  }
  ctx.putImageData(img, 0, 0);
}

function blotches(ctx, w, h, rand, count, colors, alpha = 0.12, minR = 4, maxR = 20) {
  for (let i = 0; i < count; i++) {
    const x = rand() * w, y = rand() * h;
    const r = minR + rand() * (maxR - minR);
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    const col = colors[(rand() * colors.length) | 0];
    g.addColorStop(0, `rgba(${col},${alpha})`);
    g.addColorStop(1, `rgba(${col},0)`);
    ctx.fillStyle = g;
    ctx.fillRect(x - r, y - r, r * 2, r * 2);
  }
}

function cracks(ctx, rand, count, color = 'rgba(8,8,10,0.45)', w = TEX, h = TEX) {
  for (let i = 0; i < count; i++) {
    let x = rand() * w, y = rand() * h;
    ctx.strokeStyle = color;
    ctx.lineWidth = rand() < 0.75 ? 0.7 : 1.4;
    ctx.beginPath();
    ctx.moveTo(x, y);
    const segs = 3 + (rand() * 5) | 0;
    let ang = rand() * Math.PI * 2;
    for (let s = 0; s < segs; s++) {
      ang += (rand() - 0.5) * 1.5;
      const len = 2 + rand() * 9;
      x += Math.cos(ang) * len;
      y += Math.sin(ang) * len;
      ctx.lineTo(x, y);
    }
    ctx.stroke();
  }
}

/* ---------------- wall materials ---------------- */

function concrete(rand, base = [43, 43, 48], tint = [0, 0, 0]) {
  const c = makeCanvas(TEX, TEX);
  const ctx = c.getContext('2d', { willReadFrequently: true });
  ctx.fillStyle = `rgb(${base[0]},${base[1]},${base[2]})`;
  ctx.fillRect(0, 0, TEX, TEX);

  blotches(ctx, TEX, TEX, rand, 42, ['30,30,33', '54,52,50', '22,24,26', '61,58,52'], 0.13, 5, 26);

  // Form-work seams.
  ctx.fillStyle = 'rgba(10,10,12,0.34)';
  ctx.fillRect(0, 0, TEX, 1);
  ctx.fillRect(0, TEX / 2, TEX, 1.5);
  ctx.fillStyle = 'rgba(120,116,106,0.05)';
  ctx.fillRect(0, 2, TEX, 1);
  ctx.fillRect(0, TEX / 2 + 2, TEX, 1);

  // Vertical drip stains.
  for (let i = 0; i < 10; i++) {
    const x = rand() * TEX;
    const w = 1 + rand() * 5;
    const grad = ctx.createLinearGradient(0, 0, 0, TEX);
    grad.addColorStop(0, 'rgba(12,12,14,0.05)');
    grad.addColorStop(0.6, 'rgba(12,12,14,0.2)');
    grad.addColorStop(1, 'rgba(8,8,10,0.38)');
    ctx.fillStyle = grad;
    ctx.fillRect(x, rand() * 20, w, TEX);
  }

  cracks(ctx, rand, 7);

  // Grime along the bottom edge.
  const g = ctx.createLinearGradient(0, TEX * 0.62, 0, TEX);
  g.addColorStop(0, 'rgba(10,10,11,0)');
  g.addColorStop(1, 'rgba(7,7,8,0.55)');
  ctx.fillStyle = g;
  ctx.fillRect(0, TEX * 0.62, TEX, TEX * 0.38);

  grainPixels(ctx, TEX, TEX, rand, 16);
  return packCanvas(c).data;
}

function wallpaper(rand) {
  const c = makeCanvas(TEX, TEX);
  const ctx = c.getContext('2d', { willReadFrequently: true });
  ctx.fillStyle = 'rgb(64,61,48)';
  ctx.fillRect(0, 0, TEX, TEX);

  // Vertical stripes.
  for (let x = 0; x < TEX; x += 16) {
    ctx.fillStyle = 'rgba(28,29,23,0.28)';
    ctx.fillRect(x, 0, 7, TEX);
    ctx.fillStyle = 'rgba(112,104,80,0.09)';
    ctx.fillRect(x + 9, 0, 2, TEX);
  }

  // Damask diamonds.
  ctx.strokeStyle = 'rgba(112,104,80,0.2)';
  ctx.lineWidth = 1;
  for (let y = -16; y < TEX + 16; y += 38) {
    for (let x = 8; x < TEX; x += 32) {
      const ox = ((y / 38) & 1) ? 16 : 0;
      ctx.beginPath();
      ctx.moveTo(x + ox, y);
      ctx.lineTo(x + 10 + ox, y + 12);
      ctx.lineTo(x + ox, y + 24);
      ctx.lineTo(x - 10 + ox, y + 12);
      ctx.closePath();
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(x + ox, y + 12, 3, 0, Math.PI * 2);
      ctx.stroke();
    }
  }

  // Peeling patches reveal the concrete behind.
  for (let i = 0; i < 9; i++) {
    const x = rand() * TEX, y = rand() * TEX;
    const r = 4 + rand() * 15;
    ctx.fillStyle = 'rgba(48,48,50,0.9)';
    ctx.beginPath();
    const pts = 7 + ((rand() * 6) | 0);
    for (let p = 0; p < pts; p++) {
      const a = (p / pts) * Math.PI * 2;
      const rr = r * (0.55 + rand() * 0.7);
      const px = x + Math.cos(a) * rr, py = y + Math.sin(a) * rr;
      if (p === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(16,17,16,0.5)';
    ctx.lineWidth = 1;
    ctx.stroke();
  }

  // Water damage.
  for (let i = 0; i < 8; i++) {
    const x = rand() * TEX, y = TEX * (0.5 + rand() * 0.5);
    const g = ctx.createRadialGradient(x, y, 0, x, y, 10 + rand() * 18);
    g.addColorStop(0, 'rgba(38,34,24,0.4)');
    g.addColorStop(1, 'rgba(38,34,24,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, TEX, TEX);
  }

  const g = ctx.createLinearGradient(0, TEX * 0.6, 0, TEX);
  g.addColorStop(0, 'rgba(10,10,9,0)');
  g.addColorStop(1, 'rgba(8,8,7,0.55)');
  ctx.fillStyle = g;
  ctx.fillRect(0, TEX * 0.6, TEX, TEX * 0.4);

  grainPixels(ctx, TEX, TEX, rand, 15);
  return packCanvas(c).data;
}

function metal(rand) {
  const c = makeCanvas(TEX, TEX);
  const ctx = c.getContext('2d', { willReadFrequently: true });
  ctx.fillStyle = 'rgb(38,42,46)';
  ctx.fillRect(0, 0, TEX, TEX);

  // Panels.
  for (let y = 0; y < TEX; y += 32) {
    for (let x = 0; x < TEX; x += 32) {
      ctx.fillStyle = `rgba(${52 + (rand() * 12) | 0},${56 + (rand() * 12) | 0},${60 + (rand() * 12) | 0},0.35)`;
      ctx.fillRect(x + 2, y + 2, 28, 28);
      ctx.strokeStyle = 'rgba(8,10,11,0.7)';
      ctx.lineWidth = 1.5;
      ctx.strokeRect(x + 1, y + 1, 30, 30);
    }
  }
  // Rivets.
  ctx.fillStyle = 'rgba(120,126,128,0.35)';
  for (let y = 4; y < TEX; y += 32) {
    for (let x = 4; x < TEX; x += 32) {
      ctx.beginPath(); ctx.arc(x, y, 1.6, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(x + 24, y, 1.6, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(x, y + 24, 1.6, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(x + 24, y + 24, 1.6, 0, Math.PI * 2); ctx.fill();
    }
  }
  // Rust runs.
  for (let i = 0; i < 7; i++) {
    const x = rand() * TEX, y = rand() * TEX * 0.7;
    const g = ctx.createLinearGradient(0, y, 0, y + 30 + rand() * 40);
    g.addColorStop(0, 'rgba(98,54,32,0.55)');
    g.addColorStop(1, 'rgba(68,36,22,0)');
    ctx.fillStyle = g;
    ctx.fillRect(x, y, 1 + rand() * 4, 60);
  }
  blotches(ctx, TEX, TEX, rand, 18, ['20,22,24', '70,72,70'], 0.12, 4, 18);
  grainPixels(ctx, TEX, TEX, rand, 12);
  return packCanvas(c).data;
}

function graffiti(rand) {
  const c = makeCanvas(TEX, TEX);
  const ctx = c.getContext('2d', { willReadFrequently: true });
  ctx.fillStyle = 'rgb(36,36,41)';
  ctx.fillRect(0, 0, TEX, TEX);
  blotches(ctx, TEX, TEX, rand, 34, ['22,22,25', '52,50,48'], 0.15, 5, 24);
  cracks(ctx, rand, 9);
  const g = ctx.createLinearGradient(0, TEX * 0.55, 0, TEX);
  g.addColorStop(0, 'rgba(8,8,9,0)');
  g.addColorStop(1, 'rgba(6,6,7,0.6)');
  ctx.fillStyle = g;
  ctx.fillRect(0, TEX * 0.55, TEX, TEX * 0.45);

  ctx.save();
  ctx.translate(TEX / 2, TEX / 2);
  ctx.rotate(-0.09);
  ctx.fillStyle = 'rgba(118,24,18,0.72)';
  ctx.textAlign = 'center';
  ctx.font = '700 17px "Courier New", monospace';
  ctx.fillText("DON'T", 0, -18);
  ctx.font = '700 21px "Courier New", monospace';
  ctx.fillText('LOOK', 0, 6);
  ctx.font = '700 17px "Courier New", monospace';
  ctx.fillText('BACK', 0, 28);
  // Drips.
  ctx.fillStyle = 'rgba(104,20,16,0.45)';
  for (let i = 0; i < 12; i++) {
    ctx.fillRect(-40 + rand() * 80, 28 + rand() * 4, 1, 4 + rand() * 16);
  }
  ctx.restore();
  grainPixels(ctx, TEX, TEX, rand, 16);
  return packCanvas(c).data;
}

/* ---------------- floor + ceiling ---------------- */

function floorTexture(rand) {
  const c = makeCanvas(TEX, TEX);
  const ctx = c.getContext('2d', { willReadFrequently: true });
  ctx.fillStyle = 'rgb(31,31,33)';
  ctx.fillRect(0, 0, TEX, TEX);

  // Large slabs.
  for (let y = 0; y < TEX; y += 64) {
    for (let x = 0; x < TEX; x += 64) {
      ctx.fillStyle = `rgba(${40 + (rand() * 8) | 0},${40 + (rand() * 8) | 0},${42 + (rand() * 8) | 0},0.5)`;
      ctx.fillRect(x + 1, y + 1, 62, 62);
      ctx.strokeStyle = 'rgba(9,9,10,0.8)';
      ctx.lineWidth = 2;
      ctx.strokeRect(x + 1, y + 1, 62, 62);
    }
  }
  blotches(ctx, TEX, TEX, rand, 55, ['22,22,24', '58,56,52', '17,19,20'], 0.16, 4, 28);
  cracks(ctx, rand, 16, 'rgba(5,5,6,0.55)');
  // Dust.
  for (let i = 0; i < 300; i++) {
    ctx.fillStyle = `rgba(${120 + (rand() * 50) | 0},${115 + (rand() * 40) | 0},${100 + (rand() * 40) | 0},${rand() * 0.09})`;
    ctx.fillRect(rand() * TEX, rand() * TEX, 1, 1);
  }
  grainPixels(ctx, TEX, TEX, rand, 14);
  return packCanvas(c).data;
}

function ceilingTexture(rand) {
  const c = makeCanvas(TEX, TEX);
  const ctx = c.getContext('2d', { willReadFrequently: true });
  ctx.fillStyle = 'rgb(22,23,25)';
  ctx.fillRect(0, 0, TEX, TEX);
  blotches(ctx, TEX, TEX, rand, 30, ['12,13,14', '40,40,40'], 0.15, 6, 30);
  cracks(ctx, rand, 10, 'rgba(4,4,5,0.5)');
  for (let i = 0; i < 6; i++) {
    const x = rand() * TEX, y = rand() * TEX;
    const g = ctx.createRadialGradient(x, y, 0, x, y, 8 + rand() * 20);
    g.addColorStop(0, 'rgba(56,50,28,0.13)');
    g.addColorStop(1, 'rgba(56,50,28,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, TEX, TEX);
  }
  grainPixels(ctx, TEX, TEX, rand, 10);
  return packCanvas(c).data;
}

/* ---------------- sprites ---------------- */

function drawMonster(ctx, W, H, pose = 'idle') {
  ctx.clearRect(0, 0, W, H);
  const s = W / 100;
  const cx = W / 2;

  ctx.save();
  ctx.scale(s, s * (H / (W * 2.1))); // normalized 100x210 canvas
  const unit = 100 / W; // not used, keep proportions

  const body = '#07080a';
  const rim = 'rgba(94,101,100,0.55)';
  const pale = '#a9a79b';
  const paleDark = '#6d6c63';

  // legs
  ctx.strokeStyle = body;
  ctx.lineCap = 'round';
  ctx.lineWidth = 7;
  ctx.beginPath();
  ctx.moveTo(45, 112); ctx.lineTo(40, 150); ctx.lineTo(38, 194);
  ctx.moveTo(55, 112); ctx.lineTo(60, 150); ctx.lineTo(61, 194);
  ctx.stroke();
  ctx.strokeStyle = rim;
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(38, 194); ctx.lineTo(40, 150);
  ctx.moveTo(61, 194); ctx.lineTo(60, 150);
  ctx.stroke();

  // torso
  ctx.fillStyle = body;
  ctx.beginPath();
  ctx.moveTo(38, 52);
  ctx.bezierCurveTo(31, 66, 33, 92, 40, 118);
  ctx.bezierCurveTo(47, 124, 53, 124, 60, 118);
  ctx.bezierCurveTo(67, 92, 69, 66, 62, 52);
  ctx.closePath();
  ctx.fill();
  // ribs
  ctx.strokeStyle = 'rgba(120,124,118,0.16)';
  ctx.lineWidth = 1;
  for (let i = 0; i < 5; i++) {
    const y = 68 + i * 8;
    ctx.beginPath();
    ctx.moveTo(39, y);
    ctx.quadraticCurveTo(47, y + 4, 56, y + 1);
    ctx.stroke();
  }
  // rim light
  ctx.strokeStyle = rim;
  ctx.beginPath();
  ctx.moveTo(38, 53);
  ctx.bezierCurveTo(31, 66, 33, 92, 40, 118);
  ctx.stroke();

  // arms
  ctx.strokeStyle = body;
  ctx.lineWidth = 6;
  if (pose === 'scream') {
    ctx.beginPath();
    ctx.moveTo(38, 56); ctx.quadraticCurveTo(18, 62, 10, 40);
    ctx.moveTo(62, 56); ctx.quadraticCurveTo(82, 62, 90, 40);
    ctx.stroke();
    // clawed fingers
    ctx.lineWidth = 1.8;
    ctx.beginPath();
    ctx.moveTo(10, 40); ctx.lineTo(2, 28);
    ctx.moveTo(10, 40); ctx.lineTo(8, 25);
    ctx.moveTo(10, 40); ctx.lineTo(16, 26);
    ctx.moveTo(90, 40); ctx.lineTo(98, 28);
    ctx.moveTo(90, 40); ctx.lineTo(92, 25);
    ctx.moveTo(90, 40); ctx.lineTo(84, 26);
    ctx.stroke();
  } else {
    ctx.beginPath();
    ctx.moveTo(37, 56); ctx.quadraticCurveTo(22, 78, 26, 112);
    ctx.lineTo(20, 152);
    ctx.moveTo(63, 56); ctx.quadraticCurveTo(78, 78, 74, 112);
    ctx.lineTo(80, 152);
    ctx.stroke();
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    for (let i = 0; i < 4; i++) {
      ctx.moveTo(20 + i * 2.2, 152); ctx.lineTo(16 + i * 3.2, 166 + (i & 1) * 3);
      ctx.moveTo(80 - i * 2.2, 152); ctx.lineTo(84 - i * 3.2, 166 + (i & 1) * 3);
    }
    ctx.stroke();
  }

  // neck
  ctx.fillStyle = body;
  ctx.fillRect(44, 42, 12, 16);

  // head, tilted
  ctx.save();
  ctx.translate(cx / s, 32);
  ctx.rotate(pose === 'scream' ? -0.08 : 0.12);
  const hw = pose === 'scream' ? 17 : 14;
  const hh = pose === 'scream' ? 23 : 19;
  ctx.fillStyle = body;
  ctx.beginPath();
  ctx.ellipse(0, 0, hw + 3, hh + 3, 0, 0, Math.PI * 2);
  ctx.fill();
  // pale face
  const fg = ctx.createLinearGradient(0, -hh, 0, hh);
  fg.addColorStop(0, '#bdb9ab');
  fg.addColorStop(0.55, pale);
  fg.addColorStop(1, paleDark);
  ctx.fillStyle = fg;
  ctx.beginPath();
  ctx.ellipse(0, 0, hw, hh, 0, 0, Math.PI * 2);
  ctx.fill();
  // hollow cheeks
  ctx.fillStyle = 'rgba(44,44,40,0.35)';
  ctx.beginPath();
  ctx.ellipse(-hw * 0.45, hh * 0.25, hw * 0.25, hh * 0.4, 0.2, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(hw * 0.45, hh * 0.25, hw * 0.25, hh * 0.4, -0.2, 0, Math.PI * 2);
  ctx.fill();

  // eyes
  const eyeY = -hh * 0.22;
  const eyeSpread = hw * 0.44;
  ctx.fillStyle = '#050506';
  ctx.beginPath();
  ctx.ellipse(-eyeSpread, eyeY, hw * 0.26, hh * 0.3, 0.1, 0, Math.PI * 2);
  ctx.ellipse(eyeSpread, eyeY, hw * 0.26, hh * 0.3, -0.1, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#f2efe2';
  ctx.beginPath();
  const pr = pose === 'scream' ? 2.4 : 1.5;
  ctx.arc(-eyeSpread, eyeY, pr, 0, Math.PI * 2);
  ctx.arc(eyeSpread, eyeY, pr, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.22)';
  ctx.beginPath();
  ctx.arc(-eyeSpread, eyeY, pr * 2.6, 0, Math.PI * 2);
  ctx.arc(eyeSpread, eyeY, pr * 2.6, 0, Math.PI * 2);
  ctx.fill();

  // mouth
  ctx.fillStyle = '#050506';
  if (pose === 'scream') {
    ctx.beginPath();
    ctx.ellipse(0, hh * 0.45, hw * 0.55, hh * 0.38, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#d8d3c2';
    for (let i = -3; i <= 3; i++) {
      ctx.beginPath();
      ctx.moveTo(i * hw * 0.14, hh * 0.18);
      ctx.lineTo(i * hw * 0.14 + 2, hh * 0.36);
      ctx.lineTo(i * hw * 0.14 + 4, hh * 0.18);
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(i * hw * 0.14, hh * 0.72);
      ctx.lineTo(i * hw * 0.14 + 2, hh * 0.55);
      ctx.lineTo(i * hw * 0.14 + 4, hh * 0.72);
      ctx.fill();
    }
  } else {
    ctx.beginPath();
    ctx.moveTo(-hw * 0.42, hh * 0.42);
    ctx.quadraticCurveTo(0, hh * 0.58, hw * 0.42, hh * 0.42);
    ctx.quadraticCurveTo(0, hh * 0.36, -hw * 0.42, hh * 0.42);
    ctx.fill();
    ctx.strokeStyle = 'rgba(220,214,197,0.55)';
    ctx.lineWidth = 0.8;
    ctx.stroke();
  }
  // cracks in the face
  ctx.strokeStyle = 'rgba(30,30,28,0.55)';
  ctx.lineWidth = 0.7;
  ctx.beginPath();
  ctx.moveTo(-hw * 0.7, -hh * 0.6);
  ctx.lineTo(-hw * 0.5, -hh * 0.35);
  ctx.lineTo(-hw * 0.6, -hh * 0.1);
  ctx.moveTo(hw * 0.55, -hh * 0.75);
  ctx.lineTo(hw * 0.4, -hh * 0.5);
  ctx.stroke();
  ctx.restore();

  ctx.restore();

  // Fine grain so the pixels feel photographed rather than drawn.
  const img = ctx.getImageData(0, 0, W, H);
  const d = img.data;
  const rand = mulberry32(999);
  for (let i = 0; i < d.length; i += 4) {
    if (d[i + 3] === 0) continue;
    const n = (rand() - 0.5) * 15;
    d[i] += n; d[i + 1] += n; d[i + 2] += n;
  }
  ctx.putImageData(img, 0, 0);
}

function makeMonster(pose = 'idle', w = 90, h = 189) {
  const c = makeCanvas(w, h);
  const ctx = c.getContext('2d', { willReadFrequently: true });
  drawMonster(ctx, w, h, pose);
  return c;
}

function sigilSprite() {
  const S = 72;
  const c = makeCanvas(S, S);
  const ctx = c.getContext('2d', { willReadFrequently: true });
  const cx = S / 2, cy = S / 2;

  // halo
  const halo = ctx.createRadialGradient(cx, cy, 1, cx, cy, S / 2);
  halo.addColorStop(0, 'rgba(255,236,190,0.32)');
  halo.addColorStop(0.4, 'rgba(255,220,150,0.12)');
  halo.addColorStop(1, 'rgba(255,220,150,0)');
  ctx.fillStyle = halo;
  ctx.fillRect(0, 0, S, S);

  ctx.strokeStyle = 'rgba(255,240,206,0.92)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(cx, cy - 24);
  ctx.lineTo(cx + 19, cy);
  ctx.lineTo(cx, cy + 24);
  ctx.lineTo(cx - 19, cy);
  ctx.closePath();
  ctx.stroke();
  ctx.strokeStyle = 'rgba(255,240,206,0.4)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(cx, cy - 18);
  ctx.lineTo(cx + 14, cy);
  ctx.lineTo(cx, cy + 18);
  ctx.lineTo(cx - 14, cy);
  ctx.closePath();
  ctx.stroke();

  // rune
  ctx.strokeStyle = 'rgba(255,250,230,0.95)';
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(cx, cy - 12);
  ctx.lineTo(cx, cy + 12);
  ctx.moveTo(cx, cy - 8);
  ctx.lineTo(cx + 7, cy - 2);
  ctx.moveTo(cx, cy + 1);
  ctx.lineTo(cx - 7, cy + 8);
  ctx.stroke();
  ctx.fillStyle = 'rgba(255,244,210,0.9)';
  ctx.beginPath(); ctx.arc(cx, cy - 12, 1.7, 0, Math.PI * 2); ctx.fill();
  return packCanvas(c);
}

function portalSprite() {
  const W = 72, H = 128;
  const c = makeCanvas(W, H);
  const ctx = c.getContext('2d', { willReadFrequently: true });
  const cx = W / 2;
  const grad = ctx.createLinearGradient(0, 12, 0, H);
  grad.addColorStop(0, 'rgba(255,255,255,0.14)');
  grad.addColorStop(0.7, 'rgba(255,255,255,0.05)');
  grad.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.moveTo(10, H);
  ctx.lineTo(10, 42);
  ctx.quadraticCurveTo(cx, -10, W - 10, 42);
  ctx.lineTo(W - 10, H);
  ctx.closePath();
  ctx.fill();

  ctx.strokeStyle = 'rgba(255,255,255,0.85)';
  ctx.lineWidth = 3.5;
  ctx.beginPath();
  ctx.moveTo(9, H);
  ctx.lineTo(9, 42);
  ctx.quadraticCurveTo(cx, -12, W - 9, 42);
  ctx.lineTo(W - 9, H);
  ctx.stroke();

  ctx.strokeStyle = 'rgba(255,255,255,0.38)';
  ctx.lineWidth = 1.2;
  for (let i = 0; i < 7; i++) {
    const y = 22 + i * 15;
    const spread = 9 + (i > 2 ? 2 : 0);
    ctx.beginPath();
    ctx.moveTo(spread + 4, y);
    ctx.lineTo(W - spread - 4, y);
    ctx.stroke();
  }

  // Light bleeding inside the arch.
  const inner = ctx.createRadialGradient(cx, H * 0.62, 2, cx, H * 0.62, W * 0.48);
  inner.addColorStop(0, 'rgba(255,255,255,0.55)');
  inner.addColorStop(0.5, 'rgba(255,255,255,0.16)');
  inner.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = inner;
  ctx.fillRect(0, 0, W, H);
  return packCanvas(c);
}

function glowSprite() {
  const S = 96;
  const c = makeCanvas(S, S);
  const ctx = c.getContext('2d', { willReadFrequently: true });
  const g = ctx.createRadialGradient(S / 2, S / 2, 0, S / 2, S / 2, S / 2);
  g.addColorStop(0, 'rgba(255,255,255,0.85)');
  g.addColorStop(0.18, 'rgba(255,255,255,0.45)');
  g.addColorStop(0.45, 'rgba(255,255,255,0.14)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, S, S);
  return packCanvas(c);
}

function eyesSprite() {
  const W = 64, H = 22;
  const c = makeCanvas(W, H);
  const ctx = c.getContext('2d', { willReadFrequently: true });
  for (const x of [20, 44]) {
    const g = ctx.createRadialGradient(x, 11, 0, x, 11, 12);
    g.addColorStop(0, 'rgba(240,240,220,0.95)');
    g.addColorStop(0.16, 'rgba(230,230,210,0.7)');
    g.addColorStop(0.45, 'rgba(180,190,170,0.16)');
    g.addColorStop(1, 'rgba(180,190,170,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = 'rgba(10,10,10,0.8)';
    ctx.beginPath();
    ctx.ellipse(x, 11, 3.5, 3, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = 'rgba(250,250,240,1)';
    ctx.beginPath();
    ctx.arc(x, 11, 1.2, 0, Math.PI * 2);
    ctx.fill();
  }
  return packCanvas(c);
}

export function createTextures(seed = 20261031) {
  const rand = mulberry32(seed);
  const walls = [null];
  walls[1] = concrete(rand);
  walls[2] = wallpaper(rand);
  walls[3] = metal(rand);
  walls[4] = graffiti(rand);

  const monsterCanvas = makeMonster('idle', 96, 202);
  const screamCanvas = makeMonster('scream', 240, 504);

  return {
    wall: walls,
    floor: floorTexture(rand),
    ceiling: ceilingTexture(rand),
    sprites: {
      monster: packCanvas(monsterCanvas),
      scream: packCanvas(screamCanvas),
      sigil: sigilSprite(),
      portal: portalSprite(),
      glow: glowSprite(),
      eyes: eyesSprite(),
    },
    jumpscareUrl: screamCanvas.toDataURL('image/png'),
  };
}

/* ============================================================
   A small first-person software renderer: DDA walls, floor and
   ceiling casting, z-buffered billboards, warm flashlight.
   ============================================================ */

const DEG = Math.PI / 180;

export class Renderer {
  constructor(canvas, textures) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d', { alpha: false });
    this.textures = textures;
    this.w = 0;
    this.h = 0;
    this.image = null;
    this.buf = null;
    this.zbuf = null;
    this.dx2 = null;
    this.tmp = null;
    this.quality = 1;
    this.resize();
  }

  resize() {
    const aspect = Math.max(0.35, window.innerWidth / Math.max(1, window.innerHeight));
    const coarse = window.matchMedia('(pointer: coarse)').matches;
    const budget = (coarse ? 128000 : 240000) * this.quality;
    let h = Math.sqrt(budget / aspect);
    let w = h * aspect;
    w = Math.max(180, Math.min(760, Math.round(w)));
    h = Math.max(180, Math.min(720, Math.round(h)));

    if (w === this.w && h === this.h) return;
    this.w = w; this.h = h;
    this.canvas.width = w;
    this.canvas.height = h;
    this.image = this.ctx.createImageData(w, h);
    this.buf = new Uint32Array(this.image.data.buffer);
    this.zbuf = new Float32Array(w);
    this.tmp = new Uint32Array(w * 32);
    this.dx2 = new Float32Array(w);
    for (let x = 0; x < w; x++) {
      const dx = (x - w / 2) / (w * 0.5);
      this.dx2[x] = dx * dx;
    }
    this.ctx.imageSmoothingEnabled = false;
  }

  fog(d) {
    return 1 / (1 + d * d * 0.052);
  }

  render(v) {
    const w = this.w, h = this.h, buf = this.buf, zbuf = this.zbuf, tex = this.textures;
    const level = v.level;
    const px = v.px, py = v.py;
    const dirX = Math.cos(v.angle), dirY = Math.sin(v.angle);
    const aspect = w / h;
    const hfov = (70 + 16 * Math.max(0, Math.min(1, (aspect - 0.55) / 0.95))) * DEG;
    const planeLen = Math.tan(hfov / 2);
    const planeX = -dirY * planeLen, planeY = dirX * planeLen;
    const focal = (w / 2) / planeLen;
    const horizon = h * (0.5 + (v.pitch || 0)) + (v.bob || 0);
    const time = v.time || 0;
    const breakLevel = v.breakLevel || 0;
    const flicker = 0.9 + 0.1 * Math.sin(time * 23.7) * Math.sin(time * 7.3) + (v.flashPulse || 0);
    const fogCol = 0xff0a0806;

    buf.fill(fogCol);

    const rayDirX0 = dirX - planeX;
    const rayDirY0 = dirY - planeY;
    const rayDirX1 = dirX + planeX;
    const rayDirY1 = dirY + planeY;

    const focusY = horizon + h * 0.16;
    const invH = 1 / (h * 0.62);

    /* ---------------- floor + ceiling ---------------- */
    const floorTex = tex.floor.data, ceilTex = tex.ceiling.data, TS = 128;
    for (let y = Math.max(0, Math.ceil(horizon) + 1); y < h; y++) {
      const p = y - horizon;
      const rowDist = (0.5 * focal) / p;
      const fog = this.fog(rowDist);
      const dy = (y - focusY) * invH;
      const warm = 0.05 + 1.55 * fog;
      const rowBaseY = (((rowDist * 0.5 + py * 0) * 0) | 0); // silence linters
      const stepX = rowDist * (rayDirX1 - rayDirX0) / w;
      const stepY = rowDist * (rayDirY1 - rayDirY0) / w;
      let fx = px + rowDist * rayDirX0;
      let fy = py + rowDist * rayDirY0;
      const floorOff = ((((fy * TS) | 0) & 127) << 7);
      for (let x = 0; x < w; x++) {
        const r2 = this.dx2[x] + dy * dy;
        let beam = 1.35 - 2.0 * r2;
        if (beam < 0) beam = 0;
        const shade = (0.045 + beam * 1.15) * warm;
        const c = floorTex[(((fy * TS) | 0) & 127) * 128 + (((fx * TS) | 0) & 127)];
        const idx = y * w + x;
        if (shade > 0.008) {
          let r = ((c & 255) * shade * 1.05 + 2.5) | 0;
          let g = (((c >> 8) & 255) * shade * 0.99 + 3) | 0;
          let b = (((c >> 16) & 255) * shade * 0.86 + 5) | 0;
          if (r > 255) r = 255; if (g > 255) g = 255; if (b > 255) b = 255;
          buf[idx] = 0xff000000 | (b << 16) | (g << 8) | r;
        }
        fx += stepX; fy += stepY;
        void floorOff;
      }
    }

    for (let y = 0; y < Math.min(h, Math.floor(horizon)); y++) {
      const p = horizon - y;
      if (p < 1) continue;
      const rowDist = (0.5 * focal) / p;
      const fog = this.fog(rowDist);
      const dy = (horizon - h * 0.34 - y) * invH;
      const stepX = rowDist * (rayDirX1 - rayDirX0) / w;
      const stepY = rowDist * (rayDirY1 - rayDirY0) / w;
      let fx = px + rowDist * rayDirX0;
      let fy = py + rowDist * rayDirY0;
      for (let x = 0; x < w; x++) {
        const r2 = this.dx2[x] * 1.4 + dy * dy;
        let beam = 1.1 - 2.2 * r2;
        if (beam < 0) beam = 0;
        const shade = (0.025 + beam * 0.42) * fog;
        if (shade > 0.006) {
          const c = ceilTex[(((fy * TS) | 0) & 127) * 128 + (((fx * TS) | 0) & 127)];
          let r = ((c & 255) * shade * 0.92 + 2) | 0;
          let g = (((c >> 8) & 255) * shade * 0.96 + 2.5) | 0;
          let b = (((c >> 16) & 255) * shade * 1.02 + 4) | 0;
          if (r > 255) r = 255; if (g > 255) g = 255; if (b > 255) b = 255;
          buf[y * w + x] = 0xff000000 | (b << 16) | (g << 8) | r;
        }
        fx += stepX; fy += stepY;
      }
    }

    /* ---------------- walls ---------------- */
    for (let x = 0; x < w; x++) {
      const cameraX = (2 * x) / w - 1;
      const rayX = dirX + planeX * cameraX;
      const rayY = dirY + planeY * cameraX;
      let mapX = px | 0, mapY = py | 0;
      const deltaX = Math.abs(1 / (rayX || 1e-9));
      const deltaY = Math.abs(1 / (rayY || 1e-9));
      let stepX, stepY, sideX, sideY;
      if (rayX < 0) { stepX = -1; sideX = (px - mapX) * deltaX; }
      else { stepX = 1; sideX = (mapX + 1 - px) * deltaX; }
      if (rayY < 0) { stepY = -1; sideY = (py - mapY) * deltaY; }
      else { stepY = 1; sideY = (mapY + 1 - py) * deltaY; }
      let side = 0, hitType = 0, steps = 0;
      while (steps++ < 96) {
        if (sideX < sideY) { sideX += deltaX; mapX += stepX; side = 0; }
        else { sideY += deltaY; mapY += stepY; side = 1; }
        if (mapX < 0 || mapY < 0 || mapX >= level.w || mapY >= level.h) { hitType = 1; break; }
        const g = level.grid[mapY * level.w + mapX];
        if (g !== 0) { hitType = level.wallType[mapY * level.w + mapX] || 1; break; }
      }
      const perp = side === 0
        ? (sideX - deltaX)
        : (sideY - deltaY);
      const dist = Math.max(0.02, perp);
      zbuf[x] = dist;

      let lineH = focal / dist;
      if (breakLevel > 0) {
        lineH *= 1 + Math.sin(time * 1.4 + x * 0.045) * 0.012 * breakLevel;
      }
      const top = horizon - lineH * 0.5;
      const bottom = horizon + lineH * 0.5;
      let y0 = Math.max(0, Math.ceil(top));
      let y1 = Math.min(h - 1, Math.floor(bottom));
      if (y1 < y0) continue;

      // flashlight cone
      const cosA = 1 / Math.sqrt(1 + cameraX * cameraX * planeLen * planeLen);
      const beam = cosA * cosA * cosA;
      const fog = this.fog(dist);
      let shade = (0.055 + 1.95 * beam) * fog * flicker;
      if (side === 1) shade *= 0.72;
      if (hitType === 3) shade *= 0.78;
      shade = Math.min(1.45, shade);

      const texArr = tex.wall[hitType] || tex.wall[1];
      let wallX = side === 0 ? py + perp * rayY : px + perp * rayX;
      wallX -= Math.floor(wallX);
      let texX = (wallX * TS) | 0;
      if (texX < 0) texX = 0;
      if (texX >= TS) texX = TS - 1;
      if ((side === 0 && rayX > 0) || (side === 1 && rayY < 0)) texX = TS - 1 - texX;

      const texStep = TS / lineH;
      let texPos = (y0 - top) * texStep;
      const sr = shade * 1.04, sg = shade * 0.995, sb = shade * 0.88;
      let o = y0 * w + x;
      for (let y = y0; y <= y1; y++) {
        let ty = texPos | 0;
        if (ty < 0) ty = 0; else if (ty >= TS) ty = TS - 1;
        const c = texArr[ty * TS + texX];
        let r = ((c & 255) * sr + 2) | 0;
        let g = (((c >> 8) & 255) * sg + 3) | 0;
        let b = (((c >> 16) & 255) * sb + 4) | 0;
        if (r > 255) r = 255; if (g > 255) g = 255; if (b > 255) b = 255;
        buf[o] = 0xff000000 | (b << 16) | (g << 8) | r;
        texPos += texStep;
        o += w;
      }
    }

    /* ---------------- billboards ---------------- */
    const sprites = this.collectSprites(v, time);
    if (sprites.length) {
      const invDet = 1 / (planeX * dirY - dirX * planeY);
      sprites.sort((a, b) => b.dist2 - a.dist2);
      for (const s of sprites) {
        const sx = s.x - px, sy = s.y - py;
        s.dist2 = sx * sx + sy * sy;
        const tX = invDet * (dirY * sx - dirX * sy);
        const tY = invDet * (-planeY * sx + planeX * sy);
        if (tY < 0.12) continue;

        let screenX = (w / 2) * (1 + tX / tY);
        let spriteH = focal * s.worldH / tY;
        let spriteW = focal * s.worldW / tY;
        if (spriteH < 1 || spriteW < 1) continue;

        const baseY = horizon + focal * 0.5 / tY - focal * (s.elevation || 0) / tY;
        const top = baseY - spriteH;
        let left = screenX - spriteW / 2;
        let right = left + spriteW;

        // slight sway for living things
        if (s.sway) {
          const sw = Math.sin(time * 1.7 + (s.phase || 0)) * s.sway * (focal / tY);
          left += sw; right += sw; screenX += sw;
        }

        let x0 = Math.max(0, Math.floor(left));
        let x1 = Math.min(w - 1, Math.ceil(right));
        if (x1 < x0) continue;
        let y0 = Math.max(0, Math.floor(top));
        let y1 = Math.min(h - 1, Math.ceil(baseY));
        if (y1 < y0) continue;

        const spr = s.texture;
        const tw = spr.w, th = spr.h, sdata = spr.data;
        const uStep = tw / spriteW;
        const vStep = th / spriteH;
        const alpha = s.alpha == null ? 1 : s.alpha;
        if (alpha <= 0.01) continue;

        const fog = this.fog(tY);
        const lit = s.selfLit ? 1 : Math.min(1.15, 0.22 + 1.15 * fog);
        const bright = (s.brightness == null ? 1 : s.brightness) * lit * alpha;
        const tr = (s.tint ? s.tint[0] : 1) * 1.0;
        const tg = (s.tint ? s.tint[1] : 1) * 1.0;
        const tb = (s.tint ? s.tint[2] : 1) * 1.0;
        const additive = !!s.additive;

        let u = (x0 - left) * uStep;
        for (let x = x0; x <= x1; x++) {
          if (tY >= zbuf[x]) { u += uStep; continue; }
          let v = (y0 - top) * vStep;
          let o = y0 * w + x;
          for (let y = y0; y <= y1; y++) {
            let tu = u | 0, tv = v | 0;
            if (tu >= tw) tu = tw - 1; else if (tu < 0) tu = 0;
            if (tv >= th) tv = th - 1; else if (tv < 0) tv = 0;
            const c = sdata[tv * tw + tu];
            const ca = (c >>> 24) / 255;
            if (ca > 0.015) {
              const a = ca * bright;
              if (a > 0.003) {
                const sr2 = ((c & 255) * tr) | 0;
                const sg2 = (((c >> 8) & 255) * tg) | 0;
                const sb2 = (((c >> 16) & 255) * tb) | 0;
                if (additive) {
                  const bg = buf[o];
                  let r = (bg & 255) + (sr2 * a) | 0;
                  let g = ((bg >> 8) & 255) + (sg2 * a) | 0;
                  let b = ((bg >> 16) & 255) + (sb2 * a) | 0;
                  if (r > 255) r = 255; if (g > 255) g = 255; if (b > 255) b = 255;
                  buf[o] = 0xff000000 | (b << 16) | (g << 8) | r;
                } else {
                  const bg = buf[o];
                  const br = bg & 255, bgc = (bg >> 8) & 255, bb = (bg >> 16) & 255;
                  let r = (br + (sr2 - br) * a) | 0;
                  let g = (bgc + (sg2 - bgc) * a) | 0;
                  let b = (bb + (sb2 - bb) * a) | 0;
                  if (r > 255) r = 255; if (g > 255) g = 255; if (b > 255) b = 255;
                  buf[o] = 0xff000000 | (b << 16) | (g << 8) | r;
                }
              }
            }
            v += vStep;
            o += w;
          }
          u += uStep;
        }
      }
    }

    /* ---------------- fracture tearing ---------------- */
    if (v.tear > 0) {
      const bands = 5 + ((v.tear * 4) | 0);
      for (let i = 0; i < bands; i++) {
        const bandH = 2 + ((Math.sin(i * 12.9898 + time * 31) * 0.5 + 0.5) * 18) | 0;
        const y0 = ((Math.sin(i * 78.233 + time * 7.7) * 0.5 + 0.5) * (h - bandH)) | 0;
        const shift = ((Math.sin(i * 43.12 + time * 13.1) * 0.5 + 0.5) * 2 - 1) * w * 0.18 * v.tear | 0;
        const src = y0 * w;
        const count = Math.min(bandH, Math.floor(this.tmp.length / w));
        this.tmp.set(buf.subarray(src, src + count * w));
        for (let r = 0; r < count; r++) {
          const dst = (y0 + r) * w;
          if (shift > 0) {
            buf.set(this.tmp.subarray(r * w, r * w + (w - shift)), dst + shift);
            buf.fill(0xff050608, dst, dst + Math.min(shift, w));
          } else if (shift < 0) {
            const sh = -shift;
            buf.set(this.tmp.subarray(r * w + sh, r * w + w), dst);
            buf.fill(0xff050608, dst + w - Math.min(sh, w), dst + w);
          }
        }
      }
    }

    /* ---------------- grain (in-buffer, subtle) ---------------- */
    if (v.grain) {
      const n = v.grain;
      let seed = (time * 977) | 0;
      for (let i = 0; i < n; i++) {
        seed = (seed * 1664525 + 1013904223) | 0;
        const idx = (seed >>> 0) % buf.length;
        const c = buf[idx];
        let r = (c & 255) + 7, g = ((c >> 8) & 255) + 7, b = ((c >> 16) & 255) + 7;
        if (r > 255) r = 255; if (g > 255) g = 255; if (b > 255) b = 255;
        buf[idx] = 0xff000000 | (b << 16) | (g << 8) | r;
      }
    }

    this.ctx.putImageData(this.image, 0, 0);
    return { w, h, focal, horizon };
  }

  collectSprites(v, time) {
    const sprites = [];
    const tex = this.textures.sprites;

    if (v.sigils) {
      for (const s of v.sigils) {
        if (s.collected) continue;
        const bob = Math.sin(time * 1.3 + s.x) * 0.06;
        sprites.push({
          x: s.x, y: s.y, texture: tex.sigil, worldH: 0.55, worldW: 0.55,
          elevation: 1.05 + bob, selfLit: true, brightness: 1.0, additive: true,
          tint: [1.0, 0.88, 0.62], dist2: 0,
        });
        sprites.push({
          x: s.x, y: s.y, texture: tex.glow, worldH: 1.9, worldW: 1.9,
          elevation: 1.15 + bob, selfLit: true, brightness: 0.5 + 0.14 * Math.sin(time * 2.1 + s.y),
          additive: true, tint: [1.0, 0.78, 0.4], dist2: 0,
        });
      }
    }

    if (v.portal) {
      const p = v.portal;
      const tint = p.unlocked ? [0.55, 1.0, 0.96] : [1.0, 0.3, 0.22];
      const pulse = p.unlocked ? 0.85 + 0.15 * Math.sin(time * 2.6) : 0.35;
      sprites.push({
        x: p.x, y: p.y, texture: tex.portal, worldH: 2.05, worldW: 1.18,
        elevation: 0, selfLit: true, brightness: pulse, additive: true,
        tint, dist2: 0,
      });
      sprites.push({
        x: p.x, y: p.y, texture: tex.glow, worldH: 3.1, worldW: 3.1,
        elevation: 1.05, selfLit: true, brightness: p.unlocked ? 0.55 : 0.22,
        additive: true, tint, dist2: 0,
      });
    }

    if (v.monster && v.monster.alpha > 0.01) {
      const m = v.monster;
      sprites.push({
        x: m.x, y: m.y, texture: m.scream ? tex.scream : tex.monster,
        worldH: m.scream ? 2.15 : 2.02, worldW: m.scream ? 1.02 : 0.96,
        elevation: 0, brightness: 0.9, alpha: m.alpha,
        sway: 0.035, phase: m.phase || 0, tint: m.tint || [1, 1, 1], dist2: 0,
      });
    }

    if (v.echoes) {
      for (const e of v.echoes) {
        sprites.push({
          x: e.x, y: e.y, texture: tex.monster, worldH: 2.0, worldW: 0.95,
          elevation: 0, brightness: 0.5, alpha: e.alpha, additive: false,
          tint: [0.75, 0.85, 0.9], dist2: 0,
        });
      }
    }

    if (v.watchers) {
      for (const w of v.watchers) {
        sprites.push({
          x: w.x, y: w.y, texture: tex.eyes, worldH: 0.22, worldW: 0.64,
          elevation: w.height, selfLit: true, brightness: 0.9, alpha: w.alpha,
