  grad.addColorStop(0, 'rgba(255,255,255,0.14)');
  grad.addColorStop(0.7, 'rgba(255,255,255,0.05)');
  grad.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.moveTo(10, H);
  ctx.lineTo(10, 42);
  ctx.quadraticCurveTo(cx, -10, W - 10, 42);
  ctx.lineTo(W - 10, H);
  ctx.closePath();
  ctx.fill();

  ctx.strokeStyle = 'rgba(255,255,255,0.85)';
  ctx.lineWidth = 3.5;
  ctx.beginPath();
  ctx.moveTo(9, H);
