  ctx.quadraticCurveTo(cx, -12, W - 9, 42);
  ctx.lineTo(W - 9, H);
  ctx.stroke();

  ctx.strokeStyle = 'rgba(255,255,255,0.38)';
  ctx.lineWidth = 1.2;
  for (let i = 0; i < 7; i++) {
