  for (const e of eyes) {
    ctx.save();
    ctx.translate(e.x, e.y);
    ctx.rotate(e.rot);
    ctx.fillStyle = '#020303';
    ctx.beginPath();
    ctx.ellipse(0, 0, e.rx, e.ry, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = 'rgba(44,46,42,0.5)';
    ctx.beginPath();
    ctx.ellipse(0, -e.ry * 0.52, e.rx * 0.85, e.ry * 0.3, 0, 0, Math.PI * 2);
    ctx.fill();
    // The pupil is only a suggestion.
    ctx.fillStyle = 'rgba(198,193,174,0.5)';
    ctx.beginPath();
    ctx.ellipse(0, e.ry * 0.05, 6, 9, 0, 0, Math.PI * 2);
    ctx.fill();
