  ctx.ellipse(16, hh * 0.2, 7, 18, -0.3, 0, Math.PI * 2);
  ctx.fill();

  // The scream.
  const mw = hw * 0.5, mh = hh * 0.44;
  const mouth = new Path2D();
  mouth.ellipse(0, hh * 0.57, mw, mh, 0, 0, Math.PI * 2);
  const throat = ctx.createRadialGradient(0, hh * 0.7, 4, 0, hh * 0.6, mw * 1.2);
