  ctx.moveTo(-hw * 0.45, -hh * 0.08);
  ctx.quadraticCurveTo(-hw * 0.5, hh * 0.18, -hw * 0.38, hh * 0.46);
  ctx.moveTo(hw * 0.45, -hh * 0.1);
  ctx.quadraticCurveTo(hw * 0.5, hh * 0.2, hw * 0.4, hh * 0.4);
  ctx.stroke();

