content.text:
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('pageerror', e => console.log('PAGEERROR:', e.message));
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.waitForTimeout(400);
await page.click('#startBtn');
await page.waitForTimeout(1200);
const straight = await page.evaluate(() => {
  const g = window.__DLB.game;
  const L = g.level;
  // find 5-length horizontal or vertical open run
  for (let y = 1; y < L.h - 1; y++) {
    for (let x = 1; x < L.w - 4; x++) {
      let ok = true;
      for (let i = 0; i < 5; i++) if (L.grid[y * L.w + x + i] !== 0) ok = false;
      if (ok) return { x, y, dir: 0 };
    }
  }
  for (let x = 1; x < L.w - 1; x++) {
    for (let y = 1; y < L.h - 4; y++) {
      let ok = true;
      for (let i = 0; i < 5; i++) if (L.grid[(y + i) * L.w + x] !== 0) ok = false;
      if (ok) return { x, y, dir: 1 };
    }
  }
  return null;
});
console.log('straight', straight);
if (straight) {
  const a = straight.dir === 0 ? 0 : Math.PI / 2;
  await page.evaluate(({ s, a }) => {
    const g = window.__DLB.game;
    g.player.x = s.x + 0.5; g.player.y = s.y + 0.5;
    g.player.angle = a;
    const d = s.dir === 0 ? { x: 2.6, y: 0 } : { x: 0, y: 2.6 };
    g.monster.x = g.player.x + d.x; g.monster.y = g.player.y + d.y;
    g.monster.path = [];
  }, { s: straight, a });
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/shots/monster-mid.png' });
  await page.evaluate(() => { const g = window.__DLB.game; g.monster.x = g.player.x + Math.cos(g.player.angle) * 1.15; g.monster.y = g.player.y + Math.sin(g.player.angle) * 1.15; });
  await page.waitForTimeout(400);
  await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/shots/monster-close.png' });
  await page.evaluate(() => { const g = window.__DLB.game; g.player.pitch = -0.08; });
  await page.waitForTimeout(200);
  await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/shots/monster-close2.png' });
}
// sigil / portal
await page.evaluate(() => { const g = window.__DLB.game; g.player.x = g.sigils[0].x - 2.2; g.player.y = g.sigils[0].y; g.player.angle = 0; g.player.pitch = 0; g.monster.x = g.level.monsterSpawn.x + .5; g.monster.y = g.level.monsterSpawn.y + .5; });
await page.waitForTimeout(400);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/shots/sigil.png' });
await page.evaluate(() => { const g = window.__DLB.game; g.player.x = g.level.exit.x + .5 - 2.4; g.player.y = g.level.exit.y + .5; g.player.angle = 0; });
await page.waitForTimeout(400);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/shots/portal-locked.png' });
await page.evaluate(() => window.__DLB.collectAllSigils());
await page.waitForTimeout(400);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/shots/portal-open.png' });
// fracture visuals
await page.evaluate(() => { window.__DLB.setGaze(0.95); });
