import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const results = [];
const check = (name, ok, extra = '') => { results.push({ name, ok: !!ok, extra }); console.log((ok ? 'PASS ' : 'FAIL ') + name + (extra ? ' :: ' + extra : '')); };
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.waitForTimeout(600);
check('menu visible', await page.isVisible('#menu'));
check('title text', (await page.textContent('.title')).replace(/\s+/g, ' ').trim().includes("DON'T LOOK BACK"));
await page.click('#startBtn');
await page.waitForTimeout(900);
let st = await page.evaluate(() => window.__DLB.state);
check('start enters play', st.mode === 'playing', st.mode);
check('hud visible', await page.isVisible('#hud'));
check('three sigils placed', st.level.sigils.length === 3, String(st.level.sigils.length));

// corridor in front of the player
const straight = await page.evaluate(() => {
  const g = window.__DLB.game, L = g.level;
  for (let y = 1; y < L.h - 1; y++) for (let x = 1; x < L.w - 5; x++) {
    let ok = true;
    for (let i = 0; i < 6; i++) if (L.grid[y * L.w + x + i] !== 0) ok = false;
    if (ok) return { x, y };
  }
  return null;
});
check('found test corridor', !!straight);
await page.evaluate(({ s }) => {
  const g = window.__DLB.game;
  g.player.x = s.x + 0.5; g.player.y = s.y + 0.5; g.player.angle = 0;
  g.monster.x = g.player.x + 3.0; g.monster.y = g.player.y; g.monster.path = [];
  g.monster.unseen = 0; g.monster.boost = 0;
  g.state.gaze = 0;
}, { s: straight });
await page.waitForTimeout(700);
st = await page.evaluate(() => window.__DLB.state);
check('monster observed in corridor', st.observed, JSON.stringify({ m: st.monster, p: st.player }));
const frozen0 = st.monster;
const gaze0 = st.gaze;
await page.waitForTimeout(1600);
st = await page.evaluate(() => window.__DLB.state);
const frozenDelta = Math.hypot(st.monster.x - frozen0.x, st.monster.y - frozen0.y);
check('monster frozen while watched', frozenDelta < 0.06, 'delta=' + frozenDelta.toFixed(3));
check('gaze rises while watching', st.gaze > gaze0 + 0.1, `gaze ${gaze0.toFixed(2)} -> ${st.gaze.toFixed(2)}`);

const beforeUnseen = st.monster;
await page.evaluate(() => { const g = window.__DLB.game; g.player.angle = Math.PI; });
await page.waitForTimeout(1600);
st = await page.evaluate(() => window.__DLB.state);
const movedUnseen = Math.hypot(st.monster.x - beforeUnseen.x, st.monster.y - beforeUnseen.y);
check('monster advances when unseen', movedUnseen > 0.1, 'delta=' + movedUnseen.toFixed(2));

// fracture
await page.evaluate(() => {
  const g = window.__DLB.game;
  g.player.angle = 0;
  g.monster.x = g.player.x + 2.5; g.monster.y = g.player.y; g.monster.path = []; g.monster.boost = 0;
  g.state.gaze = 0.995;
});
await page.waitForTimeout(300);
st = await page.evaluate(() => window.__DLB.state);
check('gaze fracture costs reality', st.reality === 2, 'reality=' + st.reality);
check('fracture raises break level', st.breakLevel >= 1, 'brk=' + st.breakLevel);
check('fracture body class', await page.evaluate(() => document.body.classList.contains('reality-broken-1')));

// sigil pickup
const beforeSig = (await page.evaluate(() => window.__DLB.state)).sigils;
await page.evaluate(() => window.__DLB.goToSigil(0));
await page.waitForTimeout(500);
st = await page.evaluate(() => window.__DLB.state);
check('sigil collected on touch', st.sigils === beforeSig + 1, `${beforeSig} -> ${st.sigils}`);
check('portal locked while sigils remain', await page.evaluate(() => {
  const g = window.__DLB.game;
  return g.sigils.filter(s => s.collected).length < 3;
}));

// win
await page.evaluate(() => { window.__DLB.collectAllSigils(); window.__DLB.goToExit(); });
await page.waitForTimeout(1400);
st = await page.evaluate(() => window.__DLB.state);
check('win after all sigils + gate', st.mode === 'won', st.mode);
check('win overlay visible', await page.isVisible('#winOverlay'));
const winStats = await page.textContent('#winStats');
check('win stats populated', winStats.includes('3/3') && winStats.includes('TIME'), winStats.replace(/\s+/g, ' '));

// restart from win
await page.click('#againBtn');
await page.waitForTimeout(800);
st = await page.evaluate(() => window.__DLB.state);
check('restart from win', st.mode === 'playing' && st.sigils === 0 && st.reality === 3, `${st.mode} sigils=${st.sigils} reality=${st.reality}`);
check('win overlay hidden after restart', !(await page.isVisible('#winOverlay')));

// pause / resume
await page.evaluate(() => window.__DLB.pause());
await page.waitForTimeout(300);
check('pause overlay', await page.isVisible('#pauseOverlay'));
check('pause mode', (await page.evaluate(() => window.__DLB.state)).mode === 'paused');
await page.click('#resumeBtn');
await page.waitForTimeout(500);
check('resume mode', (await page.evaluate(() => window.__DLB.state)).mode === 'playing');

// death + jumpscare
await page.evaluate(() => { const g = window.__DLB.game; g.monster.x = g.player.x; g.monster.y = g.player.y; g.monster.path = []; });
await page.waitForTimeout(220);
let scare = await page.evaluate(() => {
  const img = document.getElementById('jumpscareImg');
  return { active: document.getElementById('jumpscare').classList.contains('active'), nw: img.naturalWidth, nh: img.naturalHeight, mode: window.__DLB.state.mode };
});
check('jumpscare triggers on catch', scare.active && scare.mode === 'dying', JSON.stringify(scare));
check('jumpscare image generated', scare.nw === 1200 && scare.nh === 800, `${scare.nw}x${scare.nh}`);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/shots/test-jumpscare.png' });
await page.waitForTimeout(1300);
check('death overlay after scare', await page.isVisible('#deathOverlay'));
check('death mode', (await page.evaluate(() => window.__DLB.state)).mode === 'dead');
await page.click('#retryBtn');
await page.waitForTimeout(700);
st = await page.evaluate(() => window.__DLB.state);
check('retry resets run', st.mode === 'playing' && st.reality === 3 && st.sigils === 0, st.mode);

check('no page errors', errors.length === 0, errors.slice(0, 4).join(' | '));
console.log('\nSUMMARY', results.filter(r => r.ok).length + '/' + results.length);
await browser.close();
EOF
